-- Managed keybinding overlay (loader).
--
-- Lets the Control Center and the keybinding overlay rebind ANY bind on
-- a Lua session without editing a single config file the user owns.
-- Loaded by hyprland.lua before keybindings.lua, it wraps hl.bind,
-- hl.unbind and hl.define_submap so every later bind call is translated
-- through a remap table generated by `horneroctl hardware keyboard
-- rebind set|reset|undo`:
--
--   ${XDG_CONFIG_HOME:-~/.config}/hypr/hornero-keybinds.lua
--   (override: HORNERO_KEYBINDS_OVERLAY_FILE)
--
-- The generated file is data only: it is loaded with an empty
-- environment, so it can name combos but cannot call anything. A missing
-- or broken file leaves every bind exactly as the config wrote it.
--
-- Semantics: a remap { from = "SUPER + Return", to = "SUPER + X" }
-- moves every reference to SUPER + Return in the global (no submap)
-- scope to SUPER + X, including hl.unbind calls in keybindings-user.lua,
-- so personal unbind/bind pairs keep working after a rebind. `to = ""`
-- disables the bind. Each combo is translated once, so swaps
-- (A -> B and B -> A) work.
--
-- Every bind made through the wrapper is also recorded, so the shell
-- can run a bind by combo without knowing how it was written:
--   hyprctl eval 'hornero_keybinds.run("SUPER + SHIFT + F")'
-- luacheck: globals hl hornero_keybinds

local M = {}

local MOD_ALIASES = {
	SUPER = "SUPER",
	WIN = "SUPER",
	META = "SUPER",
	LOGO = "SUPER",
	MOD4 = "SUPER",
	MAINMOD = "SUPER",
	ALT = "ALT",
	MOD1 = "ALT",
	CTRL = "CTRL",
	CONTROL = "CTRL",
	SHIFT = "SHIFT",
	CAPS = "CAPS",
	MOD2 = "MOD2",
	MOD3 = "MOD3",
	MOD5 = "MOD5",
}

local function trim(s)
	return (tostring(s):gsub("^%s+", ""):gsub("%s+$", ""))
end

-- canonical("ctrl + super + t") == canonical("SUPER + CTRL + T"):
-- modifiers upper-cased, aliased and sorted, key lower-cased. Only used
-- for matching; binds are always created with the display spelling.
function M.canonical(combo)
	if type(combo) ~= "string" then
		return nil
	end
	local parts = {}
	for token in combo:gmatch("[^+]+") do
		local t = trim(token)
		if t ~= "" then
			parts[#parts + 1] = t
		end
	end
	if #parts == 0 then
		return nil
	end
	local key = parts[#parts]:lower()
	local mods, seen = {}, {}
	for i = 1, #parts - 1 do
		local raw = parts[i]:upper():gsub("^%$", "")
		local name = MOD_ALIASES[raw] or raw
		if not seen[name] then
			seen[name] = true
			mods[#mods + 1] = name
		end
	end
	table.sort(mods)
	if #mods == 0 then
		return key
	end
	return table.concat(mods, " + ") .. " + " .. key
end

local function overlay_path()
	local explicit = os.getenv("HORNERO_KEYBINDS_OVERLAY_FILE")
	if explicit and explicit ~= "" then
		return explicit
	end
	local base = os.getenv("XDG_CONFIG_HOME")
	if not base or base == "" then
		base = (os.getenv("HOME") or "") .. "/.config"
	end
	return base .. "/hypr/hornero-keybinds.lua"
end

local function warn(message)
	io.stderr:write("[hornero-keybinds] " .. message .. "\n")
end

-- load_remaps returns { [canonical from] = display to } (to may be "").
function M.load_remaps(path)
	local remaps = {}
	local fh = io.open(path, "r")
	if not fh then
		return remaps
	end
	fh:close()
	local chunk, err = loadfile(path, "t", {})
	if not chunk then
		warn("ignoring " .. path .. ": " .. tostring(err))
		return remaps
	end
	local ok, data = pcall(chunk)
	if not ok or type(data) ~= "table" or type(data.remap) ~= "table" then
		warn("ignoring " .. path .. ": not a remap table")
		return remaps
	end
	for _, entry in ipairs(data.remap) do
		if type(entry) == "table" and type(entry.from) == "string" and type(entry.to) == "string" then
			local from = M.canonical(entry.from)
			local to = trim(entry.to)
			if from and (to == "" or M.canonical(to)) then
				remaps[from] = to
			end
		end
	end
	return remaps
end

-- Keep the real API across `hyprctl reload` when the Lua state survives,
-- so a reload never wraps the wrapper (which would translate twice).
local previous = rawget(_G, "hornero_keybinds")
local raw = { bind = hl.bind, unbind = hl.unbind, define_submap = hl.define_submap }
if type(previous) == "table" and type(previous._raw) == "table" and hl.bind == previous._wrapped_bind then
	raw = previous._raw
end
M._raw = raw
M.path = overlay_path()
M.remaps = M.load_remaps(M.path)
M.binds = {}

local current_submap = ""

-- translate returns the combo to use (nil when disabled) and whether a
-- remap applied. Submap binds are never remapped.
function M.translate(combo)
	if current_submap ~= "" then
		return combo, false
	end
	local canon = M.canonical(combo)
	local to = canon and M.remaps[canon]
	if to == nil then
		return combo, false
	end
	if to == "" then
		return nil, true
	end
	return to, true
end

local function registry_key(submap, combo)
	return (submap or "") .. "|" .. (M.canonical(combo) or tostring(combo))
end

-- SUPER-hold key badges (HorneroOS/shell#701): the shell shows key
-- badges while bare SUPER is held. Detection must never consume or
-- delay a real shortcut, so every bind here is a non-consuming
-- `global` bind the shell listens to (hornero:superHold*):
--   arm       Super_L/R pressed (ignore_mods: any SUPER press)
--   release   bare SUPER released (Hyprland only fires a modifier
--             release bind when no other key intervened)
--   interrupt a twin next to every global SUPER combo, added by
--             wrapped_bind below, so a combo cancels the badges.
-- Hyprland fires every bind on a combo and non_consuming passes the
-- keypress on, so the twin cannot shadow the real bind. The shell
-- hides these three names from its bind list.
M.super_hold = {
	arm = "hornero:superHoldArm",
	release = "hornero:superHoldRelease",
	interrupt = "hornero:superHoldInterrupt",
}
M._super_interrupts = {}

-- super_combo_key returns the lower-cased key when `combo` (already in
-- use for a global bind) carries SUPER plus a non-Super key.
local function super_combo_key(combo)
	local canon = M.canonical(combo)
	if not canon then
		return nil
	end
	local parts = {}
	for token in canon:gmatch("[^+]+") do
		parts[#parts + 1] = trim(token)
	end
	if #parts < 2 then
		return nil
	end
	local key = parts[#parts]
	if key == "super_l" or key == "super_r" then
		return nil
	end
	for i = 1, #parts - 1 do
		if parts[i] == "SUPER" then
			return key
		end
	end
	return nil
end

local function wrapped_bind(combo, dispatcher, opts, ...)
	local ok, target, remapped = pcall(M.translate, combo)
	if not ok then
		target, remapped = combo, false
	end
	if target == nil then
		return nil
	end
	M.binds[registry_key(current_submap, target)] = {
		combo = target,
		from = combo,
		remapped = remapped,
		submap = current_submap,
		dispatcher = dispatcher,
	}
	local result = raw.bind(target, dispatcher, opts, ...)
	-- Badge interrupt twin (#701): same combo, non-consuming, once per
	-- combo. Registered on the translated target, so rebinds move it.
	if current_submap == "" and hl.dsp and hl.dsp.global and super_combo_key(target) then
		local id = registry_key("", target)
		if not M._super_interrupts[id] then
			M._super_interrupts[id] = true
			pcall(raw.bind, target, hl.dsp.global(M.super_hold.interrupt), { non_consuming = true })
		end
	end
	return result
end

local function wrapped_unbind(combo, ...)
	local ok, target = pcall(M.translate, combo)
	if not ok then
		target = combo
	end
	if target == nil then
		return nil
	end
	M.binds[registry_key(current_submap, target)] = nil
	-- raw.unbind removes every bind on the combo, the badge twin
	-- included; forget it so a later bind re-registers the twin.
	M._super_interrupts[registry_key("", target)] = nil
	return raw.unbind(target, ...)
end

local function wrapped_define_submap(name, ...)
	local args = table.pack(...)
	for i = 1, args.n do
		local fn = args[i]
		if type(fn) == "function" then
			args[i] = function(...)
				local saved = current_submap
				current_submap = tostring(name or "")
				local results = table.pack(pcall(fn, ...))
				current_submap = saved
				if not results[1] then
					error(results[2], 0)
				end
				return table.unpack(results, 2, results.n)
			end
		end
	end
	return raw.define_submap(name, table.unpack(args, 1, args.n))
end

-- run executes the bind currently on `combo` (global scope unless a
-- submap is named). Returns true when a bind was found.
function M.run(combo, submap)
	local entry = M.binds[registry_key(submap or "", combo)]
	if not entry then
		return false
	end
	local d = entry.dispatcher
	if type(d) == "function" then
		d()
	else
		hl.dispatch(d)
	end
	return true
end

hl.bind = wrapped_bind
hl.unbind = wrapped_unbind
if raw.define_submap then
	hl.define_submap = wrapped_define_submap
end
M._wrapped_bind = wrapped_bind

-- Rebind capture: while the overlay records a new combo it parks the
-- compositor in this submap, where no global bind fires, so even taken
-- combos reach the overlay. Escape always leaves it (non-consuming, so
-- the overlay sees Escape too); the shell also resets it on every exit
-- and after a 15 s timeout.
M.capture_submap = "hornero_capture"
if raw.define_submap and hl.dsp and hl.dsp.submap then
	pcall(raw.define_submap, M.capture_submap, function()
		raw.bind("escape", hl.dsp.submap("reset"), { non_consuming = true })
	end)
end

-- Bare-Super detection for the hold badges (#701). Registered with
-- raw.bind so the rebind overlay never remaps them (they also carry
-- no entry in M.binds, so `hornero_keybinds.run` cannot fire them).
-- The shell alone decides whether badges are enabled; with them off
-- these binds fire into a no-op.
if hl.dsp and hl.dsp.global then
	for _, key in ipairs({ "Super_L", "Super_R" }) do
		pcall(raw.bind, key, hl.dsp.global(M.super_hold.arm), { ignore_mods = true, non_consuming = true })
		pcall(raw.bind, "SUPER + " .. key, hl.dsp.global(M.super_hold.release), { release = true })
	end
end

hornero_keybinds = M
return M
